import { createEffect, createRenderEffect, onCleanup } from "solid-js";
import { register } from "./register.js";

// The shape of @solid-primitives/timer's createTimer: a numeric delay
// registers a cleanup and returns; an accessor delay creates an effect.
export function useTicker(fn, delay) {
  if (typeof delay === "number") {
    register(fn, delay);
    return;
  }
  createEffect(() => delay(), () => fn());
}

export function useMaybe(flag, fn) {
  if (flag) onCleanup(fn);
}

// The package schedules the callback itself: running it unowned is the
// package's doing, whatever owner its caller has.
export function useLater(fn) {
  setTimeout(() => onCleanup(fn));
}

function cleanupNow() {
  onCleanup(() => {});
}

// One cleanup runs for every boolean input, from a different call site.
export function choice(flag) {
  if (flag) cleanupNow();
  if (!flag) cleanupNow();
}

// The cleanup runs after an `await`: unowned whatever the caller's owner.
export async function later() {
  await Promise.resolve();
  onCleanup(() => {});
}

// The branch is the package's own state, not an argument, so no call decides
// it: each site is an alternative that a handler's unowned call may run.
const preferRender = Math.random() < 0.5;
const flag = Math.random() < 0.5;

// Joint: the two branches create an owned effect on every exit between them,
// though neither creates one on every call alone.
export function useListener(t, fn) {
  if (preferRender) createEffect(() => t, () => fn());
  else createRenderEffect(() => t, () => fn());
}

// The early return skips both branches on some calls, so no cover.
export function useSkippable(t, fn) {
  if (flag) return;
  if (preferRender) createEffect(() => t, () => fn());
  else createRenderEffect(() => t, () => fn());
}

// An async body is not modeled as a cover.
export async function useListenerAsync(t, fn) {
  if (preferRender) createEffect(() => t, () => fn());
  else createRenderEffect(() => t, () => fn());
}

// The branches sit in a `try`, whose completions are not modeled as a cover.
export function useTried(t, fn) {
  try {
    if (preferRender) createEffect(() => t, () => fn());
    else createRenderEffect(() => t, () => fn());
  } catch {
    /* the effect may not be created */
  }
}

// An effect and a cleanup are different operations: no joint effect cover.
export function useMixed(t, fn) {
  if (preferRender) createEffect(() => t, () => fn());
  else onCleanup(fn);
}
